import sys
from collections import deque, defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = defaultdict(list)
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    start_node = 1
    end_node = n

    dist = [-1] * (n + 1)
    dist[start_node] = 0
    queue = deque([start_node])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    max_dist = dist[end_node]
    if max_dist == -1:
        print(f"{0.0:.10f}")
        return

    count = [0] * (max_dist + 1)

    def dfs_paths(u, d, current_count):
        if d > max_dist:
            return
        if u == end_node:
            count[d] += 1
            return

        for v in adj[u]:
            if dist[v] == d + 1:
                dfs_paths(v, d + 1, current_count)

    dfs_paths(start_node, 0, 0)

    total_paths = sum(count)
    if total_paths == 0:
        print(f"{0.0:.10f}")

    best_avg = 0.0

    for station in range(1, n + 1):
        total_safe = 0
        path_count = 0

        def dfs_count_safe(u, d, safe_road_count):
            nonlocal total_safe, path_count
            if d > max_dist:
                return
            if u == end_node:
                total_safe += safe_road_count
                path_count += 1
                return

            for v in adj[u]:
                if dist[v] == d + 1:
                    is_safe = (u == station or v == station)
                    dfs_count_safe(v, d + 1, safe_road_count + (1 if is_safe else 0))

        dfs_count_safe(start_node, 0, 0)

        if path_count > 0:
            avg = total_safe / path_count
            if avg > best_avg:
                best_avg = avg

    print(f"{best_avg:.10f}")

if __name__ == "__main__":
    solve()
